</form>

<div class="table-responsive"><table class="table dealer-list" role="table"><caption><?= $total ?> matching dealers</caption><thead role="rowgroup"><tr role="row"><?php foreach(['#','Dealer Name','Mobile','Email','Login'] as $label): ?><th scope="col" role="columnheader"><?= $label ?></th><?php endforeach ?></tr></thead><tbody role="rowgroup">
<?php foreach($rows as $index=>$row): ?><tr role="row" data-login-member="<?= (int)$row['membership_id'] ?>"><td class="dealer-number" role="cell"><?= ($page-1)*$perPage+$index+1 ?></td><th scope="row" role="rowheader"><?= esc($row['erp_name']) ?></th>
<td role="cell" data-label="Mobile"><?= esc($row['erp_mobile']?:'Not recorded') ?></td><td role="cell" data-label="Email" class="<?= empty($row['erp_email'])?'dealer-muted':'' ?>"><?= esc($row['erp_email']?:'Not recorded') ?></td><td role="cell" data-label="Login"><?php $login=$logins[(int)$row['membership_id']]??null; ?><small class="d-block mb-1" data-account-label><?= $login?esc($login['normalized_identifier'].' / '.($login['revoked_at']?'Revoked':((int)$login['enabled']?'Enabled':'Disabled'))):'No login' ?></small><button type="button" class="btn btn-sm btn-outline-primary" data-dealer-login="<?= (int)$row['membership_id'] ?>"><?= $login?'Manage Login':'Create Login' ?></button></td></tr><?php endforeach ?>
<?php if(!$rows): ?><tr role="row"><td role="cell" colspan="5" class="dealer-empty"><?= array_sum($counts)===0?'No registered dealers are available yet. Please contact Shalimar Properties administration.':'No dealers match your search.' ?></td></tr><?php endif ?>
